<?php
declare(strict_types=1);require dirname(__DIR__).'/config/bootstrap.php';
use InaudisVote\Core\Authorization;use InaudisVote\Core\Csrf;use InaudisVote\Core\Navigation;use InaudisVote\Services\ElectionService;
$user=Authorization::requireRoles(['admin']);$id=(int)($_GET['id']??0);$election=ElectionService::find($id);
if(!$election||!Authorization::canManageElection($user,(int)$election['organization_id'],$id)){http_response_code(404);exit('Votación no encontrada.');}
$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!Csrf::validate($_POST['_csrf']??null))$error='Solicitud inválida.';
 else try{$action=(string)($_POST['action']??'');if($action==='update_details')ElectionService::updateDetails($id,$_POST);elseif($action==='otp_ttl')ElectionService::setOtpTtl($id,(int)($_POST['otp_ttl_minutes']??0));elseif($action==='add_question')ElectionService::addQuestion($id,$_POST);elseif($action==='update_question')ElectionService::updateQuestion($id,(int)($_POST['question_id']??0),$_POST);elseif($action==='delete_question')ElectionService::deleteQuestion($id,(int)($_POST['question_id']??0));else throw new RuntimeException('Acción no permitida en configuración.');header('Location: /election.php?id='.$id.'&ok=1');exit;}catch(Throwable $exception){$error=$exception->getMessage();}
}
$election=ElectionService::find($id);$questions=ElectionService::questions($id);$editable=in_array($election['status'],['draft','scheduled'],true)&&empty($election['ballot_locked_at']);$statusClass=$election['status']==='open'?'v-status-open':($election['status']==='closed'?'v-status-closed':'v-status-draft');
?>
<!doctype html><html lang="es"><head><link rel="icon" type="image/png" href="/assets/democra-mark.png"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=htmlspecialchars($election['title'])?> | DEMOCRA</title><link rel="stylesheet" href="/assets/quorum.css"><link rel="stylesheet" href="/assets/democra.css"></head><body class="vota-ui"><div class="v-shell">
<?php Navigation::sidebar($user, 'configuration', $id, $election['title']); ?>
<div class="v-main"><header class="v-topbar"><a class="v-link" href="/control.php?election_id=<?=$id?>">← Volver al centro de control</a><span style="flex:1"></span><a class="v-link" href="/logout.php">Salir</a></header><main class="v-content">
<div class="v-headrow"><div><div class="v-kicker"><?=htmlspecialchars($election['organization_name'])?></div><h1 class="v-title">Configuración de papeleta</h1><div class="v-accent-line"></div><p class="v-subtitle"><?=htmlspecialchars((string)$election['description'])?></p></div><span class="v-status <?=$statusClass?>"><?=htmlspecialchars($election['status'])?></span></div>
<?php if(isset($_GET['ok'])):?><div class="v-alert v-alert-ok">✓ Cambio guardado correctamente.</div><?php endif;?><?php if($error):?><div class="v-alert v-alert-error"><?=htmlspecialchars($error)?></div><?php endif;?><?php if(!$editable):?><div class="v-alert v-alert-warn"><strong>Papeleta bloqueada.</strong> La configuración queda en modo de solo lectura después de abrir.</div><?php endif;?>
<?php if($editable):?><details class="v-card v-pad" style="margin-bottom:20px"><summary><strong>Editar datos generales</strong></summary><form method="post" class="v-stack" style="margin-top:18px"><?=Csrf::input()?><input type="hidden" name="action" value="update_details"><label class="v-label">Título<input class="v-field" name="title" maxlength="180" required value="<?=htmlspecialchars((string)$election['title'],ENT_QUOTES)?>"></label><label class="v-label">Descripción<textarea class="v-field" name="description" rows="3"><?=htmlspecialchars((string)$election['description'])?></textarea></label><div class="v-grid-2" style="grid-template-columns:1fr 1fr"><label class="v-label">Inicio<input class="v-field" type="datetime-local" name="starts_at" value="<?=!empty($election['starts_at'])?htmlspecialchars(date('Y-m-d\TH:i',strtotime((string)$election['starts_at'])),ENT_QUOTES):''?>"></label><label class="v-label">Término<input class="v-field" type="datetime-local" name="ends_at" value="<?=!empty($election['ends_at'])?htmlspecialchars(date('Y-m-d\TH:i',strtotime((string)$election['ends_at'])),ENT_QUOTES):''?>"></label></div><button class="v-btn v-btn-primary">Guardar datos generales</button></form></details><?php endif;?>
<div class="v-grid-2" style="grid-template-columns:2fr 1fr"><section class="v-stack"><div class="v-card v-pad"><div class="v-section-head"><h2 style="margin:0">Papeleta</h2><span class="v-muted"><?=count($questions)?> pregunta(s)</span></div><?php if(!$questions):?><p class="v-muted">Agrega la primera pregunta para preparar el proceso.</p><?php endif;?><?php foreach($questions as $question):?><article style="border-top:1px solid var(--line);padding:18px 0"><div class="v-section-head"><div><strong><?=htmlspecialchars($question['text'])?></strong><div class="v-muted" style="font-size:12px;margin-top:4px"><?=htmlspecialchars($question['question_type'])?> · <?php if($question['question_type']==='multiple'):?>mín. <?=$question['min_choices']?> · máx. <?=$question['max_choices']?><?php else:?>una respuesta<?php endif;?></div></div><?php if($editable):?><form method="post" onsubmit="return confirm('¿Eliminar esta pregunta?');"><?=Csrf::input()?><input type="hidden" name="action" value="delete_question"><input type="hidden" name="question_id" value="<?=$question['id']?>"><button class="v-btn v-btn-danger">Eliminar</button></form><?php endif;?></div><?php foreach($question['options'] as $option):?><div class="v-option" style="cursor:default;padding:10px 13px"><span>○</span><?=htmlspecialchars($option['label'])?></div><?php endforeach;?></article><?php endforeach;?></div>
<?php if($editable&&$questions):?><div class="v-card v-pad"><h2 style="margin-top:0">Editar preguntas</h2><p class="v-muted">Corrige el enunciado, tipo o alternativas antes de abrir la votación.</p><?php foreach($questions as $question):?><details style="border-top:1px solid var(--line);padding:14px 0"><summary><strong><?=htmlspecialchars($question['text'])?></strong></summary><form method="post" class="v-stack" style="margin-top:14px"><?=Csrf::input()?><input type="hidden" name="action" value="update_question"><input type="hidden" name="question_id" value="<?=(int)$question['id']?>"><label class="v-label">Pregunta<textarea class="v-field" name="text" required><?=htmlspecialchars($question['text'])?></textarea></label><label class="v-label">Tipo<select class="v-field" name="question_type"><option value="single" <?=$question['question_type']==='single'?'selected':''?>>Selección única</option><option value="multiple" <?=$question['question_type']==='multiple'?'selected':''?>>Selección múltiple</option></select></label><div class="v-grid-2" style="grid-template-columns:1fr 1fr"><label class="v-label">Mínimo de respuestas<input class="v-field js-min-choices" type="number" name="min_choices" min="1" value="<?=(int)$question['min_choices']?>"></label><label class="v-label">Máximo de respuestas<input class="v-field js-max-choices" type="number" name="max_choices" min="1" value="<?=(int)$question['max_choices']?>"></label></div><label class="v-label">Alternativas, una por línea<textarea class="v-field" name="options" required rows="5"><?=htmlspecialchars(implode("\n",array_column($question['options'],'label')))?></textarea></label><button class="v-btn v-btn-primary">Guardar cambios de esta pregunta</button></form></details><?php endforeach;?></div><?php endif;?>
<?php if($editable):?><div class="v-card v-pad"><h2 style="margin-top:0">Agregar pregunta</h2><form method="post" class="v-stack"><?=Csrf::input()?><input type="hidden" name="action" value="add_question"><textarea class="v-field" name="text" required placeholder="Escribe la pregunta"></textarea><select class="v-field" name="question_type"><option value="single">Selección única</option><option value="multiple">Selección múltiple</option></select><div class="v-grid-2" style="grid-template-columns:1fr 1fr"><label class="v-label">Mínimo de respuestas<input class="v-field" type="number" name="min_choices" min="1" value="1"></label><label class="v-label">Máximo de respuestas<input class="v-field" type="number" name="max_choices" min="1" value="1"></label></div><textarea class="v-field" name="options" required rows="5" placeholder="Una alternativa por línea"></textarea><button class="v-btn v-btn-orange">＋ Agregar pregunta</button></form></div><?php endif;?></section>
<aside class="v-stack"><div class="v-card v-pad"><h2 style="margin-top:0">Vigencia del código OTP</h2><p class="v-muted">El enlace y el código se envían juntos. Vigencia de 10 a 1440 minutos desde su generación.</p><?php if($editable):?><form method="post" class="v-stack"><?=Csrf::input()?><input type="hidden" name="action" value="otp_ttl"><label class="v-label" for="otp_ttl_minutes">Minutos de vigencia</label><input class="v-field" id="otp_ttl_minutes" type="number" name="otp_ttl_minutes" min="10" max="1440" required value="<?=(int)$election['otp_ttl_minutes']?>"><button class="v-btn v-btn-primary">Guardar vigencia</button></form><?php else:?><strong><?=(int)$election['otp_ttl_minutes']?> minutos</strong><?php endif;?></div><div class="v-card v-pad"><h2 style="margin-top:0">Estado del proceso</h2><p class="v-muted">Los cambios de estado se realizan únicamente desde el Centro de Control, con confirmación y trazabilidad.</p><a class="v-btn v-btn-primary" href="/control.php?election_id=<?=$id?>">Ir al Centro de Control →</a></div><div class="v-card v-pad"><h2 style="margin-top:0">Resumen</h2><p><span class="v-muted">Modo</span><br><strong><?=htmlspecialchars($election['voting_mode'])?></strong></p><p><span class="v-muted">Ponderado</span><br><strong><?=$election['allow_weighted_vote']?'Sí':'No'?></strong></p><p><span class="v-muted">Inicio</span><br><?=htmlspecialchars((string)$election['starts_at'])?></p><p><span class="v-muted">Término</span><br><?=htmlspecialchars((string)$election['ends_at'])?></p></div></aside></div>
</main></div></div>
<script>
document.querySelectorAll('select[name="question_type"]').forEach(function(select){
 const form=select.closest('form'); if(!form)return;
 const boxes=form.querySelectorAll('input[name="min_choices"],input[name="max_choices"]');
 function sync(){const multiple=select.value==='multiple';boxes.forEach(function(i){const l=i.closest('label');if(l)l.style.display=multiple?'block':'none';i.disabled=!multiple;});}
 select.addEventListener('change',sync);sync();
});
</script></body></html>
